-- 116_staff_calendar_birthday_messages_seed.sql
-- Staff Calendar: the starter birthday messages (70 in all, 14 for each tag: Funny, Cherished, Tech, Sheng, Blessing). They use {first_name}.
-- Safe to run twice and on the live site: a message is added only when no message with the same text is already there, so nothing is ever duplicated.
-- The messages page can switch any of them off, and tutors can suggest more.
INSERT INTO staff_calendar_birthday_messages (body, tag, is_active, status)
SELECT x.body, x.tag, 1, 'approved' FROM (
SELECT 'Happy Birthday, {first_name}! Another year older, and still the only person who knows where the good chairs are hidden. 🎂' AS body, 'Funny' AS tag
    UNION ALL SELECT '{first_name}, you are not getting older, you are getting more experienced at ignoring the office thermostat. Happy Birthday!', 'Funny'
    UNION ALL SELECT 'Breaking news: {first_name} has completed another lap around the sun with no crashes. Congratulations, and happy birthday!', 'Funny'
    UNION ALL SELECT 'Happy Birthday, {first_name}! May your day be free of meetings that could have been a short message.', 'Funny'
    UNION ALL SELECT '{first_name}, today the cake is compulsory and the marking is optional. Enjoy your day!', 'Funny'
    UNION ALL SELECT 'Happy Birthday {first_name}! We checked, and you officially do not look a day over very well rested.', 'Funny'
    UNION ALL SELECT 'Another year wiser, {first_name}. The wisdom has not yet reached the team WhatsApp group, but we have hope. Happy Birthday!', 'Funny'
    UNION ALL SELECT 'Today we celebrate {first_name}, a person who has survived countless group projects. Respect. Happy Birthday! 🎉', 'Funny'
    UNION ALL SELECT '{first_name}, may your wifi be strong, your tea be hot, and your cake arrive before the speeches. Happy Birthday!', 'Funny'
    UNION ALL SELECT 'Happy Birthday, {first_name}! Scientists confirm that birthdays are the only deadline nobody asks to extend.', 'Funny'
    UNION ALL SELECT '{first_name}, you have been upgraded to a new version of yourself. No release notes, but we like it. Happy Birthday!', 'Funny'
    UNION ALL SELECT 'Let the record show that on this day {first_name} was officially allowed to ignore the diet. Happy Birthday! 🍰', 'Funny'
    UNION ALL SELECT 'Happy Birthday {first_name}! Your candles are now a fire hazard, which means you are doing life right.', 'Funny'
    UNION ALL SELECT '{first_name}, we asked the cake how old you are and it said it is not allowed to say. Happy Birthday!', 'Funny'
    UNION ALL SELECT '{first_name}, Dazu is a better place with you in it. Today the whole team gets to say it out loud. Happy Birthday! 💚', 'Cherished'
    UNION ALL SELECT 'Some people make a team feel like family. That is you, {first_name}. Happy Birthday!', 'Cherished'
    UNION ALL SELECT '{first_name}, your students remember how you made them feel long after they forget the lesson. Thank you, and happy birthday.', 'Cherished'
    UNION ALL SELECT 'Happy Birthday, {first_name}! The quiet things you do for this team never go unnoticed.', 'Cherished'
    UNION ALL SELECT '{first_name}, we are lucky to work beside you. Today is all about you, so please take the compliments. Happy Birthday!', 'Cherished'
    UNION ALL SELECT 'Happy Birthday {first_name}. Thank you for the patience, the laughter, and the cups of tea you never mention.', 'Cherished'
    UNION ALL SELECT '{first_name}, the best part of Dazu is the people, and you are very high on that list. Happy Birthday! 🎂', 'Cherished'
    UNION ALL SELECT 'Today we say it out loud, {first_name}: we are glad you are here. Happy Birthday!', 'Cherished'
    UNION ALL SELECT '{first_name}, you have a way of making hard days lighter. May this one be gentle and full of good people. Happy Birthday.', 'Cherished'
    UNION ALL SELECT 'Happy Birthday, {first_name}! Thank you for showing up, again and again, for the people who count on you.', 'Cherished'
    UNION ALL SELECT '{first_name}, whatever this year brings, you will not face it alone. The team is right here. Happy Birthday! 💚', 'Cherished'
    UNION ALL SELECT 'Happy Birthday {first_name}. You have changed more lives here than you will ever know.', 'Cherished'
    UNION ALL SELECT '{first_name}, thank you for being the kind of colleague people hope to find. Enjoy every minute of today.', 'Cherished'
    UNION ALL SELECT 'Happy Birthday, {first_name}! Your kindness is the first thing we would pack if Dazu ever moved house.', 'Cherished'
    UNION ALL SELECT 'Happy Birthday, {first_name}! Your uptime this year has been excellent. No unplanned downtime, only mild cake-related latency. 🎂', 'Tech'
    UNION ALL SELECT '{first_name}, you just shipped another year with zero critical bugs that we know of. Happy Birthday!', 'Tech'
    UNION ALL SELECT 'Happy Birthday {first_name}! May your code compile on the first try and your meetings never need screen sharing.', 'Tech'
    UNION ALL SELECT '{first_name}, today you get a free upgrade to the next version. Release notes: more joy, fewer bugs. Happy Birthday!', 'Tech'
    UNION ALL SELECT '{first_name}, we tried to debug your age and found out it is a feature. Happy Birthday!', 'Tech'
    UNION ALL SELECT 'Happy Birthday {first_name}! Your birthday has been merged into main. No conflicts, no rollback, only cake.', 'Tech'
    UNION ALL SELECT '{first_name}, may your passwords be strong and your backups be recent. Happy Birthday! 🔐', 'Tech'
    UNION ALL SELECT 'Status report: {first_name} is 100 percent awesome and 0 percent out of cache. Happy Birthday!', 'Tech'
    UNION ALL SELECT 'Happy Birthday, {first_name}! Today we pause every deploy and push only good vibes.', 'Tech'
    UNION ALL SELECT '{first_name}, may your wifi never drop in the middle of a lesson. Happy Birthday, and many more years of stable builds!', 'Tech'
    UNION ALL SELECT 'Happy Birthday {first_name}! Today the only thing allowed to crash is the party. 🎉', 'Tech'
    UNION ALL SELECT '{first_name}, you are the kind of person who makes the whole system run smoother. Happy Birthday!', 'Tech'
    UNION ALL SELECT 'Happy Birthday {first_name}. No pull request is needed today, just come and cut the cake.', 'Tech'
    UNION ALL SELECT '{first_name}, may this year bring fast laptops, short stand-ups and long weekends. Happy Birthday!', 'Tech'
    UNION ALL SELECT 'Poa {first_name}! Leo ni siku yako, hakuna stress, ni keki tu na vibe. Happy Birthday!', 'Sheng'
    UNION ALL SELECT 'Niaje {first_name}! Leo tunakuinua, wewe ni mtu wa maana sana kwa mbogi hii. Happy Birthday! 🎂', 'Sheng'
    UNION ALL SELECT 'Mambo {first_name}! Leo wacha kazi ikae kando, ni siku yako. Happy Birthday, uko juu!', 'Sheng'
    UNION ALL SELECT '{first_name}, msee wetu, leo ni form yako. Kula keki, chill, na ufurahie. Happy Birthday!', 'Sheng'
    UNION ALL SELECT 'Happy Birthday {first_name}! Mwaka mpya, ngori zimepungua, mambo ni fiti. Uko poa!', 'Sheng'
    UNION ALL SELECT 'Wah {first_name}, ni leo! Siku yako imefika na tumeleta vibe safi. Happy Birthday bro!', 'Sheng'
    UNION ALL SELECT 'Happy Birthday {first_name}! Leo hakuna mtu atakusumbua, ni siku ya kuchill na kula keki.', 'Sheng'
    UNION ALL SELECT 'Aki {first_name}, wewe ni mtu poa sana. Tunafurahi kuwa na wewe kwa mbogi. Happy Birthday! 🎉', 'Sheng'
    UNION ALL SELECT '{first_name}, mwaka huu uwe na chapaa, amani na vibes tu. Happy Birthday, tuko pamoja!', 'Sheng'
    UNION ALL SELECT 'Happy Birthday {first_name}! Leo ni siku ya kupiga story, kucheka na kuchukua slice ya keki kubwa.', 'Sheng'
    UNION ALL SELECT 'Fiti sana {first_name}! Mwaka mpya, mambo mapya, na kila kitu kiende smooth. Happy Birthday!', 'Sheng'
    UNION ALL SELECT 'Happy Birthday {first_name}, mtu wangu! Leo tuko na wewe, kesho tutarudi kazi. Safi!', 'Sheng'
    UNION ALL SELECT '{first_name}, siku hii ni yako kabisa. Poa tu, enjoy kila dakika. Happy Birthday!', 'Sheng'
    UNION ALL SELECT 'Hongera {first_name}! Umefika mwaka mpya kama boss. Happy Birthday, na uendelee kuwa juu!', 'Sheng'
    UNION ALL SELECT '{first_name}, may this new year of your life be gentle with you and generous in blessings. Happy Birthday! 🙏', 'Blessing'
    UNION ALL SELECT 'Happy Birthday {first_name}. May your health stay strong, your family stay safe and your joy stay steady.', 'Blessing'
    UNION ALL SELECT '{first_name}, may doors open for you this year that nobody else could have opened. Happy Birthday!', 'Blessing'
    UNION ALL SELECT 'May this year bring {first_name} peace in the mind, rest for the body and laughter that comes easily. Happy Birthday.', 'Blessing'
    UNION ALL SELECT 'Happy Birthday {first_name}! May everything you have planted with patience grow and bear fruit this year.', 'Blessing'
    UNION ALL SELECT '{first_name}, may your path be lit, your steps be steady and your table never be empty. Happy Birthday.', 'Blessing'
    UNION ALL SELECT 'Wishing you a year of good news, {first_name}. May your cup overflow and your worries stay small. Happy Birthday! 💚', 'Blessing'
    UNION ALL SELECT 'Happy Birthday {first_name}. May you be surrounded by people who love you and work that is worthy of you.', 'Blessing'
    UNION ALL SELECT '{first_name}, may the year ahead be kinder than the one behind it. Blessings on your birthday!', 'Blessing'
    UNION ALL SELECT 'Happy Birthday {first_name}! May favour find you in the places you least expect it.', 'Blessing'
    UNION ALL SELECT '{first_name}, may you always have enough strength, enough time and enough love. Happy Birthday!', 'Blessing'
    UNION ALL SELECT 'Happy Birthday {first_name}. May every good prayer said for you today find its way home.', 'Blessing'
    UNION ALL SELECT 'May this year hold more yes than no for you, {first_name}. Blessed Birthday!', 'Blessing'
    UNION ALL SELECT '{first_name}, may you rest well, laugh often and be reminded that you are valued. Happy Birthday and God bless.', 'Blessing'
) x
WHERE NOT EXISTS (SELECT 1 FROM staff_calendar_birthday_messages m WHERE m.body = x.body);
